import type {
  IsoTimestamp,
  NotificationId,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type NotificationKind =
  | "issue_assigned"
  | "issue_status_changed"
  | "issue_due_soon"
  | "issue_overdue"
  | "comment_created"
  | "comment_mention"
  | "member_invited"
  | "member_joined"
