export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/** How many calendar months one period of this interval spans. */
export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Advances a period boundary by one interval. A monthly period ends on the
 * same day next month (or that month's last day when there is no such day —
 * 31 Jan → 28 Feb); annual works the same way a year out. Each new period
 * starts exactly where the previous one ended, so a clamped day carries
 * forward on the next call (28 Feb → 28 Mar).
 */
export function addInterval(
  value: IsoTimestamp,
  interval: BillingInterval,
): IsoTimestamp {
  return toIsoTimestamp(addMonths(parseIso(value), monthsInInterval(interval)));
}

function addMonths(date: Date, months: number): Date {
  const day = date.getUTCDate();
  const totalMonths = date.getUTCMonth() + months;
  const year = date.getUTCFullYear() + Math.floor(totalMonths / 12);
  const month = ((totalMonths % 12) + 12) % 12;
  const lastDayOfMonth = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const clampedDay = Math.min(day, lastDayOfMonth);

  return new Date(
    Date.UTC(
      year,
      month,
      clampedDay,
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/** Whole days between two boundaries, at least one. */
export function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const days = Math.round(
    (parseIso(end).getTime() - parseIso(start).getTime()) / DAY_MS,
  );
  return Math.max(1, days);
}

/** Whole or started days left from `reference` to `end`; zero once reached. */
export function daysLeftUntil(end: IsoTimestamp, reference: Date): number {
  const ms = parseIso(end).getTime() - reference.getTime();
  if (ms <= 0) return 0;
  return Math.ceil(ms / DAY_MS);
}

