 * Mid-period moves are prorated: leaving the free plan starts a fresh,
 * fully-invoiced period; a trial just swaps plan/interval and keeps its
 * period; an upgrade between two paid plans is charged the per-seat price
 * difference for the days left in the current period.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );
  const currentPlan = subscription.plan;

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const now = new Date();
  let updated: Subscription;
  let chargeCents = 0;
  let invoicePeriodStart = subscription.currentPeriodStart;
  let invoicePeriodEnd = subscription.currentPeriodEnd;

  if (subscription.status === "trialing") {
    updated = await subscriptionRepo.updateSubscriptionPlanDuringTrial(
      input.orgId,
      input.plan,
      input.interval,
    );
  } else if (currentPlan === "free" && input.plan !== "free") {
    const stamp = toIsoTimestamp(now);
    const periodEnd = addInterval(stamp, input.interval);
    updated = await subscriptionRepo.updateSubscriptionPlanNewPeriod(
      input.orgId,
      input.plan,
      input.interval,
      stamp,
      periodEnd,
    );
    chargeCents = fullChargeCents(input.plan, subscription.seats, input.interval);
    invoicePeriodStart = stamp;
    invoicePeriodEnd = periodEnd;
  } else {
    updated = await subscriptionRepo.updateSubscriptionPlan(
      input.orgId,
      input.plan,
      input.interval,
    );

    if (input.plan !== "free" && input.plan !== currentPlan) {
      const diffCentsPerSeatMonthly =
        getPlanLimits(input.plan).priceCentsPerSeatMonthly -
        getPlanLimits(currentPlan).priceCentsPerSeatMonthly;

      if (diffCentsPerSeatMonthly > 0) {
        const fullCharge =
          diffCentsPerSeatMonthly *
          subscription.seats *
          monthsInInterval(subscription.interval);
        chargeCents = prorate(
          fullCharge,
          now,
          subscription.currentPeriodStart,
          subscription.currentPeriodEnd,
        );
      }
    }
  }

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    from: currentPlan,
    to: input.plan,
  });

  await issueInvoice(
    input.orgId,
    actor.userId,
    invoicePeriodStart,
    invoicePeriodEnd,
    chargeCents,
  );

  return updated;
