/** The full charge for one period of `plan`, at `seats`, in cents. */
function fullChargeCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly *
    seats *
    monthsInInterval(interval)
  );
}

/** Scales a full-period charge by the days left over the days in the period. */
function prorate(
  fullChargeCentsAmount: number,
  now: Date,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): number {
  const total = daysInPeriod(periodStart, periodEnd);
  const left = daysLeftUntil(periodEnd, now);
  return Math.floor((fullChargeCentsAmount * left) / total);
}

/**
 * Writes the invoice, then announces it — the audit log and the owner
 * notification are subscribers on `billing.invoice_issued`, not direct
 * callers of this function. A zero charge produces no invoice at all.
 */
async function issueInvoice(
  orgId: OrgId,
  actorId: UserId | null,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
  amountCents: number,
): Promise<void> {
  if (amountCents <= 0) return;

  const invoice = await invoiceRepo.insertInvoiceForPeriod(
    orgId,
    amountCents,
    periodStart,
    periodEnd,
  );

  await emit("billing.invoice_issued", {
    orgId,
    actorId,
    occurredAt: toIsoTimestamp(new Date()),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });
}

