import type { IsoTimestamp, OrgId } from "@/types/common";

/**
 * A subscription behind on its period catches up one interval at a time,
 * invoicing every paid period it crosses, until its period end lies after
 * `now`. Cancellations whose date has arrived move the workspace to the free
 * plan. Both queries exclude subscriptions this job has already caught up —
 * running it again at the same instant finds nothing left to do.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);

    const renewable = await subscriptionRepo.listSubscriptionsForRenewal(stamp);

    for (const subscription of renewable) {
      const orgId = subscription.orgId as OrgId;
      let periodStart: IsoTimestamp = subscription.currentPeriodStart;
      let periodEnd: IsoTimestamp = subscription.currentPeriodEnd;

      while (periodEnd <= stamp) {
        const nextEnd = addInterval(periodEnd, subscription.interval);

        if (subscription.plan !== "free") {
          const amountCents =
            getPlanLimits(subscription.plan).priceCentsPerSeatMonthly *
            subscription.seats *
            monthsInInterval(subscription.interval);

          const invoice = await invoiceRepo.insertInvoiceForPeriod(
            orgId,
            amountCents,
            periodStart,
            nextEnd,
          );

          await emit("billing.invoice_issued", {
            orgId,
            actorId: null,
            occurredAt: stamp,
            invoiceId: invoice.id,
            invoiceNumber: invoice.number,
            amountCents: invoice.amountCents,
            periodStart: invoice.periodStart,
            periodEnd: invoice.periodEnd,
          });
        }

        periodStart = periodEnd;
        periodEnd = nextEnd;
      }

      await subscriptionRepo.advanceSubscriptionPeriod(orgId, periodStart, periodEnd);
      result.processed += 1;
    }

    const cancellations = await subscriptionRepo.listCancellationsDue(stamp);

    for (const subscription of cancellations) {
      const orgId = subscription.orgId as OrgId;
      const cancelAt = subscription.cancelAt;
      if (cancelAt === null) continue;

      const periodEnd = addInterval(cancelAt, "monthly");
      await subscriptionRepo.applyCancellationToFreePlan(orgId, cancelAt, periodEnd);

      await emit("billing.plan_changed", {
        orgId,
        actorId: null,
        occurredAt: stamp,
        from: subscription.plan,
        to: "free",
      });

      result.processed += 1;
    }
  });
}

